VALUES
(md5('safety:' || '보호구가 무엇인가요?')::uuid, 'An toàn lao động', '보호구가 무엇인가요?', 'Sử dụng trang thiết bị bảo hộ lao động', '["보호구는 작업 중 발생할 수 있는 위험으로부터 작업자의 신체를 보호하기 위해 착용하거나 사용하는 장비나 용품입니다.", "보호구는 작업 중 작업자의 생명과 건강을 지키기 위한 필수 장비입니다"]'::jsonb, 'Sản xuất chế tạo', 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:' || '보호구에는 어떤 종류가 있나요?')::uuid, 'An toàn lao động', '보호구에는 어떤 종류가 있나요?', 'Sử dụng trang thiết bị bảo hộ lao động', '["안전모, 안전화, 안전대, 보안면, 귀마개, 방진마스크,방독마스크, 방열복, 방한복 등이 있습니다.", "안전모는 작업자가 물체와 부딪치거나 바닥으로 떨어졌을 때 머리를 보호하는 모자입니다.", "안전모는 충격으로부터 머리를 보호하는 모자입니다.", "안전화는 떨어지는 공구 또는 뾰족한 물건으로부터 발을 보호하기 위한 신발입니다.", "안전화는 작업 중 발을 보호하는 신발입니다.", "안전대는 작업자가 높은 곳에서 바닥으로 떨어지는 것을 막는 장비입니다.", "보안면은 불꽃이나 날아오는 물체로부터 얼굴과 눈을 보호하기 위한 장비입니다.", "보안면은 작업 중 얼굴과 눈을 보호하는 장비입니다.", "귀마개는 시끄럽고 큰 소리가 나는 장소에서 귀를 보호하기 위한 용품입니다.", "귀마개는 큰 소리로부터 귀를 보호하는 용품입니다.", "방진마스크는 공기 중에 있는 먼지로부터 입과 코를 보호하기 위한 용품입니다.", "방진마스크는 먼지로부터 입과 코를 보호하는 용품입니다.", "방독마스크는 공기 중에 있는 화학물질 등으로부터 입과 코를 보호하기 위한 용품입니다.", "방독마스크는 화학물질로부터 입과 코를 보호하는 용품입니다.", "방열복은 매우 뜨거운 장소에서 열과 불로부터 몸을 보호하기 위한 작업복입니다.", "방열복은 열과 불로부터 몸을 보호하는 작업복입니다.", "방한복은 매우 추운 장소에서 몸 온도를 유지하기 위한 보온용 작업복입니다.", "한복은 몸을 따뜻하게 하는 작업복입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:' || '보호구를 왜 착용하여야 할까요?')::uuid, 'An toàn lao động', '보호구를 왜 착용하여야 할까요?', 'Sử dụng trang thiết bị bảo hộ lao động', '["보호구를 착용하여야 하는 이유는 작업자의 생명과 건강을 지키기 위한 가장 기본적이고 필수적인 조치이기 때문입니다.", "보호구는 작업자의 생명과 건강을 지키기 위해 착용하기 때문입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:' || '머리를 보호하기 위해 착용하는 보호구는 무엇인가요?')::uuid, 'An toàn lao động', '머리를 보호하기 위해 착용하는 보호구는 무엇인가요?', 'Sử dụng trang thiết bị bảo hộ lao động', '["머리를 보호하기 위해서는 안전모를 착용해야 합니다.", "안전모 착용 시에는 턱끈을 조여야 합니다.", "안전모를 착용해야 합니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:' || '높은 장소에서 작업 시 안전모 외에 착용해야 하는 보호구는 무엇인가요?')::uuid, 'An toàn lao động', '높은 장소에서 작업 시 안전모 외에 착용해야 하는 보호구는 무엇인가요?', 'Sử dụng trang thiết bị bảo hộ lao động', '["높은 장소에서 작업하는 경우에는 안전대를 착용하고, 안전대 부착설비에 고리를 체결해야 합니다.", "높은 장소에서 작업 시 안전대를 착용하고 고리를 체결해야 합니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 1, '보호구 착용', 'Sử dụng trang thiết bị bảo hộ lao động'),
(md5('safety:' || '비상구가 무엇인가요?')::uuid, 'An toàn lao động', '비상구가 무엇인가요?', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm', '["비상구란: 화재, 지진 등 갑작스러운 사고가 일어났을 때 신속하게 대피할 수 있도록 마련된 출입구입니다.", "비상구는 화재나 지진 등 사고가 났을 때 대피하는 출입구입니다.", "비상구는 사고가 났을 때 대피하는 출입구입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:' || '대피로는 무엇인가요?')::uuid, 'An toàn lao động', '대피로는 무엇인가요?', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm', '["대피로는 화재 등 위급 상황이 발생했을 때 작업자가 신속하고 안전하게 빠져나갈 수 있도록 사전에 확보된 이동 경로입니다.", "대피로는 위급 상황에서 안전하게 대피하는 이동 경로입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:' || '비상구 등 대피로를 왜 확인해야 할까요?')::uuid, 'An toàn lao động', '비상구 등 대피로를 왜 확인해야 할까요?', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm', '["비상구 등 대피로를 확인해야 하는 이유는 사고가 발생하였을 때 생명을 지키기 위한 가장 기본적인 재난 대응 수칙으로 신속한 이동이 가능하기 때문입니다.", "비상구와 대피로는 사고가 났을 때 신속하게 대피하기 위해 확인해야 합니다.", "사고가 났을 때 빨리 대피하기 위해서입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:' || '소화기란 무엇이며 소화기의 색상은 어떻게 되나요?')::uuid, 'An toàn lao động', '소화기란 무엇이며 소화기의 색상은 어떻게 되나요?', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm', '["소화기란 불을 끄기 위한 도구로 보통은 붉은색 입니다. 평소에 소화기의 위치를 확인해 두는 것이 중요합니다.", "소화기란 불을 끄기 위한 도구로 보통은 붉은색입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 2, '비상구 등 대피로 확인', 'Kiểm tra cửa thoát hiểm và lối thoát hiểm'),
(md5('safety:' || '안전보건표지가 무엇인가요?')::uuid, 'An toàn lao động', '안전보건표지가 무엇인가요?', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động', '["안전보건표지란 작업장 내 위험요인을 알리고, 안전한 행동을 유도하기 위해 사용하는 시각적 표지입니다.", "안전보건표지는 위험을 알리고 안전한 행동을 유도하는 표지입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động'),
(md5('safety:' || '안전보건표지에는 어떤 종류가 있을까요?')::uuid, 'An toàn lao động', '안전보건표지에는 어떤 종류가 있을까요?', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động', '["안전보건표지의 종류에는 위험행동을 막기 위한 금지표지, 위험에 대한 주의 위험 경고 표시, 안전행동 유도를 위한 지시표시, 대피경로 등을 알려주기 위한 안내표지가 있습니다.", "안전보건표지는 금지표지, 경고표지, 지시표지, 안내표지가 있습니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động'),
(md5('safety:' || '위험장소 출입금지 등 금지표지는 무슨 색인가요?')::uuid, 'An toàn lao động', '위험장소 출입금지 등 금지표지는 무슨 색인가요?', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động', '["출입 금지 등 위험 행동을 막기 위한 금지표지는 붉은색 원 모양에 붉은색으로 사선이 그려져 있습니다.", "금지표지는 위험 행동을 막는 표지로, 붉은색 원에 붉은 사선이 있습니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 3, '안전보건표지 확인', 'Kiểm tra biển báo an toàn, vệ sinh trong lao động'),
(md5('safety:' || '방호장치가 무엇인가요?')::uuid, 'An toàn lao động', '방호장치가 무엇인가요?', 'Kiểm tra thiết bị an toàn có hoạt động hay không', '["방호장치는 기계 등에서 발생하는 위험 요인으로부터 작업자의 신체를 보호하거나 위험을 차단하는 설비입니다.", "방호장치는 위험 요인으로부터 신체를 보호하거나 위험을 차단하는 설비입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:' || '정상 작동이 무슨 뜻인가요?')::uuid, 'An toàn lao động', '정상 작동이 무슨 뜻인가요?', 'Kiểm tra thiết bị an toàn có hoạt động hay không', '["정상 작동이란 장치, 설비 등이 정해진 목적과 기준에 맞게 안전하고 정확하게 작동하는 상태입니다.", "정상 작동은 장치와 설비가 기준에 맞게 안전하게 작동하는 상태입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:' || '방호장치 정상 작동 여부를 왜 확인하여야 하나요?')::uuid, 'An toàn lao động', '방호장치 정상 작동 여부를 왜 확인하여야 하나요?', 'Kiểm tra thiết bị an toàn có hoạt động hay không', '["방호장치 정상 작동 여부를 확인하는 이유는 사람이 실수를 하더라도 방호장치가 정상적으로 작동해야만 실질적인 보호 효과가 있기 때문입니다.", "방호장치가 정상 작동해야 사람이 실수를 하더라도 작업자를 안전하게 보호할 수 있기 때문입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:' || '작업 전 안전점검이 무엇인가요?')::uuid, 'An toàn lao động', '작업 전 안전점검이 무엇인가요?', 'Kiểm tra thiết bị an toàn có hoạt động hay không', '["작업 시작 전 기계의 정상 작동 여부를 점검합니다. 기계에서 이상한 소리가 나거나 흔들리거나 하면 사용하지 말고 반장님 등 관리자에게 보고해야 합니다.", "작업 전에 기계를 점검하고, 이상이 있으면 사용하지 말고 관리자에게 보고해야 합니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 4, '방호장치 정상 작동 여부 확인', 'Kiểm tra thiết bị an toàn có hoạt động hay không'),
(md5('safety:' || '화학물질이 무엇인가요?')::uuid, 'An toàn lao động', '화학물질이 무엇인가요?', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)', '["화학물질이란 사업장에서 제품을 만드는 데 사용하는 고체, 액체, 기체로 사람에게 유해하거나 폭발 등의 위험성을 가진 물질입니다.", "사업장에서 사용하는 고체·액체·기체로, 인체에 유해하거나 폭발 등의 위험성이 있는 물질입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:' || 'MSDS(물질안전보건자료)가 무엇인가요?')::uuid, 'An toàn lao động', 'MSDS(물질안전보건자료)가 무엇인가요?', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)', '["MSDS(물질안전보건자료)란 화학물질에 대한 정보(이름, 성분, 유해성, 위험성, 보관방법, 다룰 때 주의할 점, 필요한 보호구, 응급조치 등)가 담긴 설명서입니다.", "MSDS 는 화학물질의 정보, 주의사항, 보호구와 응급조치가 있는 설명서입니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
(md5('safety:' || '화학물질 MSDS(물질안전보건자료)를 왜 확인해야 할까요?')::uuid, 'An toàn lao động', '화학물질 MSDS(물질안전보건자료)를 왜 확인해야 할까요?', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)', '["화학물질 MSDS(물질안전보건자료)를 확인해야 하는 이유는 화학물질을 안전하게 취급하고 사고를 예방하기 위해 반드시 확인해야 하는 가장 기본적인 안전정보이기 때문입니다.", "화학물질을 안전하게 취급하고 사고를 예방하기 위해 MSDS 를 확인해야 합니다."]'::jsonb, 'Sản xuất chế tạo', 'before_work', 5, '화학물질 MSDS(물질안전보건자료) 확인', 'Kiểm tra MSDS (Bảng dữ liệu an toàn hóa chất)'),
